@font-face{font-family:"IBM Plex Sans";src:url(/v9/fonts/plex-latin-ext.woff2) format("woff2");font-weight:100 700;unicode-range:U+0100-02AF,U+1E00-1EFF,U+20A0-20CF}
@font-face{font-family:"IBM Plex Sans";src:url(/v9/fonts/plex-latin.woff2) format("woff2");font-weight:100 700;unicode-range:U+0000-00FF,U+2000-206F,U+2190-21FF}
